def _items(state: Mapping[str, Any], key: str) -> list[dict[str, Any]]:
    rows = state.get(key)
    return [dict(row) for row in rows if isinstance(row, Mapping)] if isinstance(rows, list) else []


def _number(value: Any) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return float("nan")


def _summary(row: Mapping[str, Any]) -> dict[str, Any]:
    allowed = {"seq", "type", "transactionId", "disputeId", "caseNumber", "reason", "paymentId", "billerId", "fromAccountId", "amount", "scheduledDate", "recipientId", "recipientName", "bank", "mask", "transferId", "memo", "q", "total"}
    return {key: row.get(key) for key in allowed if key in row}


class OpenBankTask03702660Evaluator(BaseEvaluator):
    EVALUATOR_ID = EVALUATOR_ID
    RULESET_SPEC = RULESET_SPEC
    RULESET_SHA256 = RULESET_SHA256
    CHECKPOINT_SPECS = CHECKPOINT_SPECS

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        controller = context.get("controller")
        if controller is None or not hasattr(controller, "run_python_script"):
            return self._error("controller.run_python_script is required")
        port = int(dict(context.get("params") or {}).get("port", 4340))
        try:
            state = self._fetch_state(controller, port)
            observation = controller.observe(include_ui_tree=True, include_screenshot_data=False)
            return self.evaluate_state(
                state,
                foreground_app=str(observation.foreground_app or ""),
                foreground_window=str(observation.foreground_window or ""),
            )
        except Exception as exc:
            return self._error(f"OpenBank evaluation error: {type(exc).__name__}: {exc}")

    @classmethod
    def evaluate_state(cls, state: Mapping[str, Any], *, foreground_app: str = "openbank.exe", foreground_window: str = "OpenBank") -> EvalResult:
        checks: list[dict[str, Any]] = []
        all_events = _items(state, "events")
        logins = [row for row in all_events if row.get("type") == "session_login_success"]
        login = logins[-1] if logins else None
        start_seq = int((login or {}).get("seq", -1))
        events = [row for row in all_events if int(row.get("seq", -1)) > start_seq]
        ordered_events: list[Mapping[str, Any] | None] = []

        disputes = _items(state, "disputes")
        for index, expected in enumerate(RULESET_SPEC["disputes"]):
            object_matches = [row for row in disputes if row.get("merchant") == expected["merchant"] and row.get("reason") == expected["reason"] and row.get("contactedMerchant") is True and row.get("details") == expected["details"] and row.get("status") == "Submitted"]
            target = object_matches[0] if len(object_matches) == 1 else None
            search, detail, submit = find_dispute_route(events, target, expected)
            passed = len(object_matches) == 1 and search is not None and detail is not None and submit is not None
            checks.append(cls._check(CHECKPOINT_SPECS[index], passed, {"object_count": len(object_matches), "search": _summary(search or {}), "detail": _summary(detail or {}), "submit": _summary(submit or {}), "object": target or object_matches}))
            ordered_events.append(submit)

        payments = _items(state, "billPayments")
        for offset, expected in enumerate(RULESET_SPEC["bill_payments"], start=4):
            matches = [row for row in payments if row.get("billerId") == expected["billerId"] and row.get("fromAccountId") == expected["fromAccountId"] and _number(row.get("amount")) == expected["amount"] and row.get("scheduledDate") == expected["scheduledDate"] and row.get("memo") == expected["memo"] and row.get("status") == "Scheduled"]
            target = matches[0] if len(matches) == 1 else None
            event_matches = [row for row in events if target and row.get("type") == "bill_payment_scheduled" and row.get("paymentId") == target.get("id") and row.get("billerId") == expected["billerId"] and row.get("fromAccountId") == expected["fromAccountId"] and _number(row.get("amount")) == expected["amount"] and row.get("scheduledDate") == expected["scheduledDate"]]
            event = event_matches[0] if len(event_matches) == 1 else None
            checks.append(cls._check(CHECKPOINT_SPECS[offset], target is not None and event is not None, {"object_count": len(matches), "object": target or matches, "event": _summary(event or {})}))
            ordered_events.append(event)

        recipient_expected = RULESET_SPEC["recipient"]
        recipients = _items(state, "recipients")
        recipient_matches = [row for row in recipients if all(row.get(key) == value for key, value in recipient_expected.items())]
        recipient = recipient_matches[0] if len(recipient_matches) == 1 else None
        recipient_event_matches = [row for row in events if recipient and row.get("type") == "transfer_recipient_added" and row.get("recipientId") == recipient.get("id") and row.get("recipientName") == recipient_expected["name"] and row.get("bank") == recipient_expected["bank"] and row.get("mask") == recipient_expected["mask"]]
        recipient_event = recipient_event_matches[0] if len(recipient_event_matches) == 1 else None
        checks.append(cls._check(CHECKPOINT_SPECS[7], recipient is not None and recipient_event is not None, {"object_count": len(recipient_matches), "object": recipient or recipient_matches, "event": _summary(recipient_event or {})}))
        ordered_events.append(recipient_event)

        transfer_expected = RULESET_SPEC["transfer"]
        transfers = _items(state, "transfers")
        transfer_matches = [row for row in transfers if recipient and str(row.get("id") or "").startswith("transfer-") and row.get("recipientId") == recipient.get("id") and all((_number(row.get(key)) == value if key == "amount" else row.get(key) == value) for key, value in transfer_expected.items())]
        transfer = transfer_matches[0] if len(transfer_matches) == 1 else None
        transfer_event_matches = [row for row in events if transfer and row.get("type") == "transfer_scheduled" and row.get("transferId") == transfer.get("id") and row.get("recipientId") == recipient.get("id") and row.get("fromAccountId") == transfer_expected["fromAccountId"] and _number(row.get("amount")) == transfer_expected["amount"] and row.get("scheduledDate") == transfer_expected["scheduledDate"] and row.get("memo") == transfer_expected["memo"]]
        transfer_event = transfer_event_matches[0] if len(transfer_event_matches) == 1 else None
        checks.append(cls._check(CHECKPOINT_SPECS[8], transfer is not None and transfer_event is not None, {"object_count": len(transfer_matches), "object": transfer or transfer_matches, "event": _summary(transfer_event or {})}))
        ordered_events.append(transfer_event)

        order_actual = [_summary(row or {}) for row in ordered_events]
        order_passed = all(ordered_events) and all(int(left.get("seq", -1)) < int(right.get("seq", -1)) for left, right in zip(ordered_events, ordered_events[1:]))
        checks.append(cls._check(CHECKPOINT_SPECS[9], bool(order_passed), order_actual))
        foreground_passed = foreground_app.casefold() in {"openbank", "openbank.exe"} and "openbank" in foreground_window.casefold()
        checks.append({"name": "foreground_openbank", "value_contract_id": "openbank.task03.foreground", "instruction_steps": list(range(1, 77)), "match_mode": "FINAL_UI_APP_EXACT", "expected": {"app": "openbank.exe", "window": "OpenBank"}, "actual": {"app": foreground_app, "window": foreground_window}, "passed": foreground_passed})

        covered = {step for spec in CHECKPOINT_SPECS for step in spec["steps"]}
        if covered != set(range(1, 77)):
            return cls._error("checkpoint map does not cover exactly steps 1..76", checks)
        failed = [row["name"] for row in checks if not row["passed"]]
        metadata = {"task_id": TASK_ID, "read_only": True, "source_state_mode": "human_completed_eval_only", "business_state_mutations": [], "evaluator_id": EVALUATOR_ID, "ruleset_sha256": RULESET_SHA256, "ruleset_spec": RULESET_SPEC, "step_groups": STEP_GROUPS, "checkpoint_specs": CHECKPOINT_SPECS, "covered_instruction_steps": list(range(1, 77)), "checks": checks, "failed_checks": failed}
        return EvalResult(status=EvalStatus.FAIL if failed else EvalStatus.PASS, message=("OpenBank task03 evaluation failed: " + ", ".join(failed)) if failed else "All OpenBank task03 checks passed", metadata=metadata)

    @staticmethod
    def _check(spec: Mapping[str, Any], passed: bool, actual: Any) -> dict[str, Any]:
        return {"name": str(spec["value_contract_id"]), "value_contract_id": spec["value_contract_id"], "instruction_steps": list(spec["steps"]), "match_mode": spec["match_mode"], "expected": spec["expected"], "actual": actual, "passed": bool(passed)}

    @classmethod
    def _error(cls, message: str, checks: list[dict[str, Any]] | None = None) -> EvalResult:
        return EvalResult(status=EvalStatus.ERROR, message=message, metadata={"task_id": TASK_ID, "read_only": True, "evaluator_id": EVALUATOR_ID, "ruleset_sha256": RULESET_SHA256, "ruleset_spec": RULESET_SPEC, "step_groups": STEP_GROUPS, "checkpoint_specs": CHECKPOINT_SPECS, "checks": checks or [], "failed_checks": [row["name"] for row in checks or [] if not row.get("passed")]})

    @staticmethod
    def _fetch_state(controller: Any, port: int) -> Mapping[str, Any]:
        code = """import urllib.request\nwith urllib.request.urlopen(%r, timeout=8) as response:\n    print(response.read().decode('utf-8'))\n""" % f"http://127.0.0.1:{port}/api/evaluation"
        result = controller.run_python_script(code, timeout=12)
        if int(result.get("returncode", -1)) != 0:
            raise RuntimeError(str(result.get("stderr") or result.get("output") or "API request failed"))
        payload = json.loads(str(result.get("stdout") or result.get("output") or ""))
        if not isinstance(payload, Mapping):
            raise TypeError("OpenBank evaluation payload must be an object")
        return payload
